const cfg = $input.first().json;
const queries = String(cfg.queries).split(',').map(s => s.trim()).filter(Boolean);
const sorts = ['sim', 'date'];          // 정확도순 + 최신순 (둘 다 받아서 중복 제거)
const out = [];
for (const q of queries) {
  for (const s of sorts) {
    for (let start = 1; start <= 901; start += 100) {   // 네이버 API는 start 최대 1000
      out.push({ json: { query: q, sort: s, start } });
    }
  }
}
return out;

const reqs = $('요청목록 생성').all();
const clean = (s) => String(s || '')
  .replace(/<[^>]*>/g, '')
  .replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&apos;|&#39;/g, "'").replace(/\s+/g, ' ').trim();

const cafeRules = [
  ['육아·맘카페',   /맘|육아|아기|베이비|키즈|아가|엄마|임신|출산/],
  ['신혼·결혼',     /신혼|결혼|웨딩|예비부부|혼수/],
  ['자취·1인가구',  /자취|원룸|1인|혼자|독립|룸메/],
  ['입주·인테리어', /인테리어|입주|아파트|이사|집|부동산|리모델링|하우스|홈/],
  ['가전·IT',       /가전|전자|IT|컴퓨터|스마트|디지털|폰|모바일|테크/],
  ['중고·장터',     /중고|나눔|장터|당근|벼룩|마켓|직거래/],
  ['지역·생활',     /맛집|동네|지역|시$|구$|군$|생활|주부|살림/],
];
const postRules = [
  ['고장·AS',     /고장|수리|AS|as|에러|오류|안\s?나|안\s?켜|안\s?돼|안\s?되|누수|물\s?샘|물이|소음|냄새|이상|결로|얼음|꺼져|꺼짐|불량|서비스센터|기사님/],
  ['설치·이전',   /설치|이전|철거|이사|배관|실외기|타공|브라켓|재설치/],
  ['구매고민',    /추천|비교|가격|뭐가|어떤|살까|구매|구입|견적|할인|특가|최저가|고민|vs|VS|신제품|모델/],
  ['후기·사용기', /후기|사용기|리뷰|써보|사용\s?해|체험|만족|내돈내산/],
  ['청소·관리',   /청소|필터|세척|관리|곰팡이|제습|건조/],
];
const pick = (rules, text, fallback) => { for (const [n, re] of rules) if (re.test(text)) return n; return fallback; };

const seen = new Set();
const rows = [];
for (const it of $input.all()) {
  const items = it.json && it.json.items;
  if (!Array.isArray(items)) continue;      // 오류 응답은 건너뜀
  const idx = it.pairedItem && it.pairedItem.item;
  const q = (reqs[idx] && reqs[idx].json.query) || '';
  for (const p of items) {
    const link = p.link || '';
    if (!link || seen.has(link)) continue;
    seen.add(link);
    const cafe = clean(p.cafename);
    const title = clean(p.title);
    const desc = clean(p.description);
    rows.push({ json: {
      카페명: cafe,
      카페주소: p.cafeurl || '',
      카페유형: pick(cafeRules, cafe, '기타·미분류'),
      글성격: pick(postRules, title + ' ' + desc, '기타'),
      제목: title,
      요약: desc,
      링크: link,
      검색어: q,
    }});
  }
}
if (!rows.length) throw new Error('수집된 글이 없습니다. Client ID/Secret과 검색 API 권한(검색)을 확인하세요.');
return rows;

const rows = $input.all().map(i => i.json);
const total = rows.length;
const count = (key) => {
  const m = new Map();
  for (const r of rows) m.set(r[key], (m.get(r[key]) || 0) + 1);
  return [...m.entries()].sort((a, b) => b[1] - a[1]);
};
const pct = (n) => Math.round(n / total * 1000) / 10;
const out = [{ json: { 구분: '전체', 항목: '수집 글 수(중복 제거)', 건수: total, '비율(%)': 100, 비고: '' } }];

for (const [k, n] of count('카페유형')) out.push({ json: { 구분: '카페유형', 항목: k, 건수: n, '비율(%)': pct(n), 비고: '' } });
for (const [k, n] of count('글성격'))   out.push({ json: { 구분: '글성격',   항목: k, 건수: n, '비율(%)': pct(n), 비고: '' } });

const cafeMap = new Map();
for (const r of rows) {
  const e = cafeMap.get(r.카페명) || { n: 0, url: r.카페주소, type: r.카페유형 };
  e.n++; cafeMap.set(r.카페명, e);
}
const cafes = [...cafeMap.entries()].sort((a, b) => b[1].n - a[1].n);
out.push({ json: { 구분: '전체', 항목: '카페 수', 건수: cafes.length, '비율(%)': '', 비고: '' } });
for (const [name, e] of cafes.slice(0, 50)) out.push({ json: { 구분: '카페별(상위50)', 항목: name, 건수: e.n, '비율(%)': pct(e.n), 비고: e.type + ' | ' + e.url } });
return out;
